import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"内核（@deepseek-ai/dsh）管理","description":"","frontmatter":{},"headers":[],"relativePath":"zh/kernel.md","filePath":"zh/kernel.md","lastUpdated":null}'),s={name:"zh/kernel.md"};function n(d,e,i,l,h,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="内核-deepseek-ai-dsh-管理" tabindex="-1">内核（@deepseek-ai/dsh）管理 <a class="header-anchor" href="#内核-deepseek-ai-dsh-管理" aria-label="Permalink to &quot;内核（@deepseek-ai/dsh）管理&quot;">​</a></h1><p>本应用内置对内核 <code>@deepseek-ai/dsh</code> 的检测与版本管理。内核驱动 DeepSeek Harness Web UI。</p><h2 id="常见操作" tabindex="-1">常见操作 <a class="header-anchor" href="#常见操作" aria-label="Permalink to &quot;常见操作&quot;">​</a></h2><h3 id="首次安装" tabindex="-1">首次安装 <a class="header-anchor" href="#首次安装" aria-label="Permalink to &quot;首次安装&quot;">​</a></h3><p>未检测到内核时，应用内会弹出安装引导，可选镜像源、是否含测试版与指定版本，一键安装。</p><h3 id="升级-切换版本" tabindex="-1">升级 / 切换版本 <a class="header-anchor" href="#升级-切换版本" aria-label="Permalink to &quot;升级 / 切换版本&quot;">​</a></h3><p>在 <strong>设置 → 内核</strong> 中：</p><ul><li><strong>检查 / 更新内核</strong>：对比当前与最新版本，点「更新内核」执行升级。</li><li><strong>版本管理</strong>：刷新版本列表（受「检测测试版」与镜像源影响），选中历史版本即可安装 / 切换（升级或回退）。</li></ul><p>升级与切换都会<strong>先安全停止 dsh</strong>（正在运行时先弹确认），成功后自动重启以运行目标版本；失败则尽量恢复原运行态并给出原因。</p><h3 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h3><p>点「卸载内核」会先停止 dsh 再移除，之后回到安装引导。若卸载失败，应用会检测目录占用原因（如仍有进程引用、只读或安全软件锁定）并提示。</p><h2 id="网络与镜像" tabindex="-1">网络与镜像 <a class="header-anchor" href="#网络与镜像" aria-label="Permalink to &quot;网络与镜像&quot;">​</a></h2><p>内核的版本列表、更新检查与安装 / 卸载都走 npm。默认官方源 <code>registry.npmjs.org</code>，国内可切换 <code>npmmirror</code> 镜像。</p><h2 id="与-应用自更新-的区别" tabindex="-1">与“应用自更新”的区别 <a class="header-anchor" href="#与-应用自更新-的区别" aria-label="Permalink to &quot;与“应用自更新”的区别&quot;">​</a></h2><ul><li><strong>内核更新</strong>：更新 <code>@deepseek-ai/dsh</code>（npm 安装/升级），在「内核」页管理。</li><li><strong>应用自更新</strong>：更新本外壳应用本身（GitHub 发布），在「关于」页管理。</li></ul>',15)])])}const k=a(s,[["render",n]]);export{u as __pageData,k as default};
